from django.core.cache import cache
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied

class DraftCheckoutSessionView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, cart_id):
        cache_key = f"checkout_cart_{cart_id}"
        cached_cart = cache.get(cache_key)
        if not cached_cart:
            return Response({'error': 'Cart session expired or not found'}, status=status.HTTP_404_NOT_FOUND)

        if str(cached_cart.get('user_id')) != str(request.user.id):
            raise PermissionDenied("You do not have access to this checkout session.")

        return Response({
            'cart_id': cart_id,
            'items': cached_cart.get('items', []),
            'shipping_address': cached_cart.get('shipping_address'),
            'billing_info': cached_cart.get('billing_info'),
            'payment_token': cached_cart.get('payment_token')
        })
